import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"一、认证与授权是两个问题","description":"","frontmatter":{"title":"一、认证与授权是两个问题"},"headers":[],"relativePath":"ch05/01.md","filePath":"ch05/01.md","lastUpdated":1789497795000}'),o={name:"ch05/01.md"};function n(s,t,i,_,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="一、认证与授权是两个问题" tabindex="-1">一、认证与授权是两个问题 <a class="header-anchor" href="#一、认证与授权是两个问题" aria-label="Permalink to &quot;一、认证与授权是两个问题&quot;">​</a></h1><p>先分清两个词，后面所有配置都围绕它们：</p><table tabindex="0"><thead><tr><th></th><th>认证（Authentication）</th><th>授权（Authorization）</th></tr></thead><tbody><tr><td>回答的问题</td><td>你是谁？</td><td>你能做什么？</td></tr><tr><td>失败的状态码</td><td><strong>401 Unauthorized</strong></td><td><strong>403 Forbidden</strong></td></tr><tr><td>失败原因</td><td>没带凭证、凭证无效或过期</td><td>凭证有效，但角色不够</td></tr><tr><td>前端应对</td><td>跳登录页</td><td>提示“无权限”，不要跳登录</td></tr></tbody></table><p><strong>401 与 403 混用是很常见的错误</strong>：用户明明登录了，却收到 401 被踢回登录页，怎么登都进不去——实际是权限不够，应该是 403。前端拿到 401 才清令牌跳登录，拿到 403 只提示。</p>',4)])])}const m=d(o,[["render",n]]);export{p as __pageData,m as default};
